css:
/* Header — sits over the hero on the homepage. */
body [data-bz-node="hdr"]{position:absolute;top:0;left:0;right:0;z-index:60;padding:16px 25px 0 24px;background:transparent}
body [data-bz-node="hdr"]>.bz-container{max-width:none;padding:0}
body [data-bz-node="hdr-row"]{display:flex;align-items:flex-start;justify-content:space-between;gap:24px}
body [data-bz-node="hdr-brand"]{flex:0 0 auto;padding-top:9px;flex-shrink:0}
body [data-bz-node="hdr-brand"] .bz-block{padding:0}
body [data-bz-node="hdr-brand"] .bz-container{padding:0}
body [data-bz-node="hdr-brand"] img{height:34px;width:auto;max-width:none}
body [data-bz-node="hdr-right"]{flex:0 1 auto;display:flex;align-items:center;justify-content:flex-end;min-width:0;height:49px;padding:0 4px 0 16px;box-sizing:border-box;background:rgba(42,39,35,.86);border-radius:6px}
body [data-bz-node="hdr-right"] .bz-block{padding:0}
body [data-bz-node="hdr-right"] .bz-container{padding:0}

/* nav pill */
body [data-bz-node="hdr-menu"] .bz-menu-wrap{flex:0 1 auto}
body [data-bz-node="hdr-menu"] .bz-nav{flex-wrap:nowrap;gap:23px;align-items:center;height:49px;padding:0}
body [data-bz-node="hdr-menu"] .bz-navitem>a{padding:0;font:700 11px/1 var(--font-body);letter-spacing:.09em;text-transform:uppercase;color:#fff;white-space:nowrap;display:inline-flex;align-items:center;gap:6px}
body [data-bz-node="hdr-menu"] .bz-navitem>a:hover{color:var(--accent)}
body [data-bz-node="hdr-menu"] .bz-navitem--has-sub>a::after{content:"";width:12px;height:12px;background:currentColor;-webkit-mask:url(/icons/chevron-down.svg) center/12px no-repeat;mask:url(/icons/chevron-down.svg) center/12px no-repeat}
body [data-bz-node="hdr-menu"] .bz-subnav{top:calc(100% + 14px);left:-16px;min-width:220px;padding:10px 0;background:rgba(32,30,27,.97);border:0;border-radius:6px;box-shadow:0 12px 32px rgba(0,0,0,.35);gap:0}
body [data-bz-node="hdr-menu"] .bz-subnav::before{content:"";position:absolute;left:0;right:0;top:-16px;height:16px}
body [data-bz-node="hdr-menu"] .bz-subnav .bz-navitem>a{display:block;padding:11px 20px;color:#fff;white-space:nowrap}
body [data-bz-node="hdr-menu"] .bz-subnav .bz-navitem>a:hover{background:rgba(255,255,255,.08);color:var(--accent)}

body [data-bz-node="hdr-search"]{margin-left:22px;width:16px;flex:0 0 16px}
body [data-bz-node="hdr-search"] .bz-container{padding:0}
body [data-bz-node="hdr-search"] figure{margin:0}
body [data-bz-node="hdr-search"] a{display:block;width:16px;height:16px}
body [data-bz-node="hdr-search"] img{width:16px;height:16px}
body [data-bz-node="hdr-cta"]{margin-left:14px;flex:0 0 auto}
body [data-bz-node="hdr-cta"] .bz-btns{margin:0}
body [data-bz-node="hdr-cta"] .bz-btn{height:39px;width:122px;min-width:122px;padding:0;display:inline-flex;align-items:center;justify-content:center;border-radius:4px;background:var(--accent);color:#fff;font:700 13px/1 var(--font-body);letter-spacing:.02em;border:0}
body [data-bz-node="hdr-cta"] .bz-btn:hover{background:var(--accent-dark)}

@media (max-width:1100px){
  body [data-bz-node="hdr"]{padding:12px 20px 0}
  body [data-bz-node="hdr-menu"] .bz-menu-toggle{background:rgba(32,30,27,.9);color:#fff;border:0;border-radius:6px;width:44px;height:44px}
  body [data-bz-node="hdr-menu"] .bz-menu-wrap[data-open]>.bz-menu{background:#2a2723;border:0;border-radius:6px;left:auto;right:0;top:calc(100% + 8px);min-width:260px;padding:8px 0;box-shadow:0 12px 32px rgba(0,0,0,.35)}
  body [data-bz-node="hdr-menu"] .bz-menu-wrap[data-open] .bz-nav{height:auto;background:none;padding:0;gap:0;flex-direction:column;align-items:stretch}
  body [data-bz-node="hdr-menu"] .bz-menu-wrap[data-open] .bz-navitem>a{padding:13px 20px;display:flex;justify-content:space-between;width:100%;box-sizing:border-box}
  body [data-bz-node="hdr-menu"] .bz-menu-wrap[data-open] .bz-subnav{position:static;display:flex;background:none;box-shadow:none;padding:0}
  body [data-bz-node="hdr-menu"] .bz-menu-wrap[data-open] .bz-subnav::before{display:none}
  body [data-bz-node="hdr-menu"] .bz-menu-wrap[data-open] .bz-subnav .bz-navitem>a{padding-left:36px;font-weight:500}
}
@media (max-width:640px){
  body [data-bz-node="hdr"]{padding:12px 12px 0}
  body [data-bz-node="hdr-row"]{gap:8px;align-items:center}
  body [data-bz-node="hdr-brand"]{padding-top:0;flex:0 1 auto;min-width:0}
  body [data-bz-node="hdr-brand"] img{height:22px;width:auto;max-width:none}
  body [data-bz-node="hdr-right"]{height:44px;padding:0 4px 0 4px;flex:0 0 auto}
  body [data-bz-node="hdr-menu"] .bz-menu-toggle{background:none;width:36px;height:36px}
  body [data-bz-node="hdr-cta"]{margin-left:4px}
  body [data-bz-node="hdr-cta"] .bz-btn{width:auto;min-width:0;height:34px;padding:0 10px;font-size:12px}
  body [data-bz-node="hdr-search"]{display:none}
}
